<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\Doctrine\QuestionBank;
use App\Application\QuestionBank\Port\QuestionPdfQuestionWriterInterface;use App\Domain\QuestionBank\Repository\QuestionDuplicateDetectorInterface;use App\Domain\QuestionBank\Repository\QuestionTaxonomyAssignmentRepositoryInterface;use App\Domain\Taxonomy\Repository\TaxonomySubjectRepositoryInterface;use App\Domain\Taxonomy\Entity\TaxonomySubject;use App\Domain\Taxonomy\Service\SubjectTaxonomyService;use App\Infrastructure\Persistence\Doctrine\QuestionBank\Entity\QuestionOptionRecord;use App\Infrastructure\Persistence\Doctrine\QuestionBank\Entity\QuestionRecord;use Doctrine\ORM\EntityManagerInterface;
final class DoctrineQuestionPdfQuestionWriter implements QuestionPdfQuestionWriterInterface { public function __construct(private readonly EntityManagerInterface $em,private readonly QuestionDuplicateDetectorInterface $duplicates,private readonly TaxonomySubjectRepositoryInterface $taxonomy,private readonly QuestionTaxonomyAssignmentRepositoryInterface $assignments,private readonly SubjectTaxonomyService $slugs){} public function write(string $createdBy,array $questions):array{$existing=$this->duplicates->findExistingByStatements(array_values(array_filter(array_map(static fn($q)=>is_array($q)&&is_string($q['statement']??null)?$q['statement']:'',$questions))));$created=0;$duplicate=0;$classified=0;$failed=0;$newSubjects=0;foreach($questions as $q){if(!is_array($q)||!is_string($q['statement']??null)||trim($q['statement'])===''||count($q['options']??[])<2){$failed++;continue;}$key=$this->norm($q['statement']);if(isset($existing[$key])){$duplicate++;continue;}$question=new QuestionRecord();$question->id=$this->id();$question->syllabusId=null;$question->statement=trim($q['statement']);$question->difficulty=in_array($q['difficulty']??null,['EASY','MEDIUM','HARD'],true)?$q['difficulty']:'MEDIUM';$question->board=is_string($q['board']??null)?mb_substr(trim($q['board']),0,190)?:null:null;$question->examYear=is_int($q['year']??null)&&$q['year']>1900&&$q['year']<2100?$q['year']:null;$question->source=is_string($q['exam']??null)?mb_substr(trim($q['exam']),0,255)?:null:null;$question->origin='EXAM';$question->status='REVIEW';$question->createdBy=$createdBy;$question->createdAt=new \DateTimeImmutable('now');$question->updatedAt=$question->createdAt;$this->em->persist($question);foreach(array_values($q['options']) as $i=>$option){if(!is_array($option)||!is_string($option['content']??null)||trim($option['content'])==='')continue;$o=new QuestionOptionRecord();$o->id=$this->id();$o->questionId=$question->id;$o->label=chr(65+$i);$o->content=$this->cleanOption((string)$option['content']);$o->sortOrder=$i+1;$o->createdAt=$question->createdAt;$this->em->persist($o);}$subject=is_string($q['subject']??null)?trim($q['subject']):'';if($subject!==''){$tax=$this->taxonomy->findBySlug($this->slugs->slug($subject))??$this->taxonomy->findByComparableSlug($this->slugs->slug($subject));if($tax===null&&mb_strlen($subject)>=3&&mb_strlen($subject)<=190){$tax=new TaxonomySubject($this->id(),null,$subject,$this->slugs->slug($subject),null,0,true);$this->taxonomy->save($tax);$newSubjects++;}if($tax!==null){$this->assignments->replaceForQuestion($question->id,[$tax->id]);$classified++;}}$existing[$key]=$question->id;$created++;}$this->em->flush();return ['created'=>$created,'duplicates'=>$duplicate,'classified'=>$classified,'failed'=>$failed,'createdSubjects'=>$newSubjects];}private function cleanOption(string $content):string{return trim((string)preg_replace('/^\s*(?:[A-Ea-e]\s*[.)\-:]\s*)+/u','',$content));}private function norm(string $s):string{return mb_strtolower((string)preg_replace('/\s+/u',' ',trim($s)));}private function id():string{$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));} }
